create extension if not exists pgcrypto;
create table if not exists public.turmas(id uuid primary key default gen_random_uuid(),codigo text unique not null,nome text not null,periodo text,criado_em timestamptz default now());
create table if not exists public.perfis(id uuid primary key references auth.users(id) on delete cascade,nome text not null,turma_id uuid not null references public.turmas(id),papel text not null default 'aluno' check(papel in('aluno','monitor','admin')),criado_em timestamptz default now());
create table if not exists public.materias(id uuid primary key default gen_random_uuid(),turma_id uuid not null references public.turmas(id) on delete cascade,nome text not null,professor text,dia_semana text,horario text,cor text default '#1F4B43',resumo text,topicos text[] default '{}',criado_em timestamptz default now());
create table if not exists public.aulas(id uuid primary key default gen_random_uuid(),materia_id uuid not null references public.materias(id) on delete cascade,data date not null,titulo text not null,status text default 'pendente' check(status in('pendente','processando','pronta')),criado_em timestamptz default now());
create table if not exists public.entregas(id uuid primary key default gen_random_uuid(),materia_id uuid not null references public.materias(id) on delete cascade,tipo text not null check(tipo in('atividade','trabalho','prova')),titulo text not null,data date not null,criado_em timestamptz default now());
create table if not exists public.anotacoes(id uuid primary key default gen_random_uuid(),materia_id uuid not null references public.materias(id) on delete cascade,aula_id uuid references public.aulas(id) on delete set null,usuario_id uuid not null references public.perfis(id),texto_original text not null,texto_organizado_ia text,tags text[] default '{}',criado_em timestamptz default now());
create table if not exists public.arquivos(id uuid primary key default gen_random_uuid(),materia_id uuid not null references public.materias(id) on delete cascade,aula_id uuid references public.aulas(id) on delete set null,enviado_por uuid not null references public.perfis(id),nome text not null,tipo text,storage_path text unique not null,criado_em timestamptz default now());
create table if not exists public.simulados_respostas(id uuid primary key default gen_random_uuid(),materia_id uuid not null references public.materias(id) on delete cascade,usuario_id uuid not null references public.perfis(id),questoes jsonb not null,respostas jsonb not null,acertos int,total int,criado_em timestamptz default now());
create or replace function public.minha_turma() returns uuid language sql stable security definer set search_path=public as $$select turma_id from perfis where id=auth.uid()$$;
create or replace function public.meu_papel() returns text language sql stable security definer set search_path=public as $$select papel from perfis where id=auth.uid()$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare tid uuid; begin select id into tid from turmas where codigo=new.raw_user_meta_data->>'codigo_turma'; if tid is null then raise exception 'Codigo de turma invalido'; end if; insert into perfis(id,nome,turma_id) values(new.id,coalesce(new.raw_user_meta_data->>'nome',split_part(new.email,'@',1)),tid); return new; end$$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
alter table turmas enable row level security; alter table perfis enable row level security; alter table materias enable row level security; alter table aulas enable row level security; alter table entregas enable row level security; alter table anotacoes enable row level security; alter table arquivos enable row level security; alter table simulados_respostas enable row level security;
create policy "turma read turmas" on turmas for select to authenticated using(id=minha_turma());
create policy "turma read perfis" on perfis for select to authenticated using(turma_id=minha_turma());
create policy "self update perfil" on perfis for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and turma_id=minha_turma());
create policy "turma read materias" on materias for select to authenticated using(turma_id=minha_turma());
create policy "staff write materias" on materias for all to authenticated using(turma_id=minha_turma() and meu_papel() in('monitor','admin')) with check(turma_id=minha_turma() and meu_papel() in('monitor','admin'));
create policy "turma read aulas" on aulas for select to authenticated using(exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()));
create policy "staff write aulas" on aulas for all to authenticated using(exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()) and meu_papel() in('monitor','admin')) with check(exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()) and meu_papel() in('monitor','admin'));
create policy "turma read entregas" on entregas for select to authenticated using(exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()));
create policy "staff write entregas" on entregas for all to authenticated using(exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()) and meu_papel() in('monitor','admin')) with check(exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()) and meu_papel() in('monitor','admin'));
create policy "turma read anotacoes" on anotacoes for select to authenticated using(exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()));
create policy "user insert anotacoes" on anotacoes for insert to authenticated with check(usuario_id=auth.uid() and exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()));
create policy "owner update anotacoes" on anotacoes for update to authenticated using(usuario_id=auth.uid() or meu_papel() in('monitor','admin'));
create policy "turma read arquivos" on arquivos for select to authenticated using(exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()));
create policy "user insert arquivos" on arquivos for insert to authenticated with check(enviado_por=auth.uid() and exists(select 1 from materias m where m.id=materia_id and m.turma_id=minha_turma()));
create policy "own quiz" on simulados_respostas for all to authenticated using(usuario_id=auth.uid()) with check(usuario_id=auth.uid());
insert into storage.buckets(id,name,public) values('materiais','materiais',false) on conflict(id) do update set public=false;
create policy "turma storage read" on storage.objects for select to authenticated using(bucket_id='materiais' and (storage.foldername(name))[1]=minha_turma()::text);
create policy "turma storage insert" on storage.objects for insert to authenticated with check(bucket_id='materiais' and (storage.foldername(name))[1]=minha_turma()::text);
create policy "owner storage delete" on storage.objects for delete to authenticated using(bucket_id='materiais' and owner_id=auth.uid()::text);
